import sys, random; sys.path.insert(0,"/home/claude/method")
from itertools import combinations
import violations as V
LAWS=V.LAWS; IMP=[(a,b) for a,b,_ in V.IMP]
def implies(imp):
    d={a:set() for a in LAWS}
    for a,b in imp: d[a].add(b)          # a derivable from b
    g=True
    while g:
        g=False
        for a in LAWS:
            for b in list(d[a]):
                for c in d[b]:
                    if c not in d[a]: d[a].add(c); g=True
    return d
D=implies(IMP)
gen=[a for a in LAWS if not D[a]]
print("DESTINATIONS — invert a subset of the independent axioms; see what stays forced\n")
rows=[]
for r in range(len(gen)+1):
    for S in combinations(gen,r):
        S=set(S)
        # law X still holds if some law implying X is NOT inverted and itself holds
        free=set(S)
        g=True
        while g:
            g=False
            for X in LAWS:
                if X in free: continue
                if D[X] and all(y in free for y in D[X]):
                    free.add(X); g=True
        rows.append((sorted(S), sorted(free-S)))
for S,extra in sorted(rows,key=lambda r:(len(r[0]),r[0])):
    tag="  <-- chronology unconstrained" if "T" in extra else ""
    print(f"  invert {{{','.join(S) or '-':9s}}}  also released: {{{','.join(extra) or '-'}}}{tag}")
n=sum(1 for S,e in rows if "T" in e)
print(f"\n  destinations where time travel is possible: {n} of {len(rows)}")

print("\nSENSITIVITY — the generator count is conditional on a 9-row table.")
random.seed(3)
pool=[(a,b) for a in LAWS for b in LAWS if a!=b and (a,b) not in IMP]
for k in (1,2,3,5,8):
    cnts=[len([a for a in LAWS if not implies(IMP+random.sample(pool,k))[a]]) for _ in range(200)]
    print(f"  +{k} unknown implications -> generators {min(cnts)}..{max(cnts)}, mean {sum(cnts)/len(cnts):.2f}")
