from itertools import combinations
BOX=['T','H','L','U','DN','C','E','SD','Rdf','Rdi']
OUT=['inst','loc','em']
POS=[('T','H'),('T','E'),('T','L'),('T','DN'),('T','U'),('DN','C'),('SD','C'),
     ('H','U'),('L','C'),('Rdi','H'),('Rdf','U')]   # <-- Rdf->U ADDED
NEG=[('Rdf','T'),('Rdi','T')]
DISJ=[('E',['inst','C']),('C',['T','Rdf','Rdi']),('U',['loc','em']),('DN',['C'])]
def close(S):
    S=set(S); g=True
    while g:
        g=False
        for a,b in POS:
            if a in S and b not in S: S.add(b); g=True
    return frozenset(S)
def ok(S,extra):
    if any(a in S and b in S for a,b in NEG): return False
    for ant,ds in DISJ:
        if ant in S:
            sat=any(d in S for d in ds if d in BOX)
            if extra: sat=sat or any(d in OUT for d in ds)
            if not sat: return False
    return True
closed={close(c) for r in range(len(BOX)+1) for c in combinations(BOX,r)}
for extra,lab in [(True,'extra-box AVAILABLE'),(False,'extra-box BLOCKED')]:
    good={c for c in closed if ok(c,extra)}
    mins=[c for c in good if c and not any(d<c and d for d in good)]
    print(f'{lab}:')
    print(f'   consistent profiles {len(good)} of {len(closed)}')
    print(f'   non-empty consistent {len([c for c in good if c])}')
    print(f'   minimal: {[\"{\"+\",\".join(sorted(c))+\"}\" for c in sorted(mins,key=lambda s:(len(s),sorted(s)))]}')
    print(f'   AMPS: empty profile inadmissible -> admissible destinations = {len([c for c in good if c])}')
"

