from itertools import combinations, product
BOX=['T','H','L','U','DN','C','E','SD','Rdf','Rdi']
POS=[('T','H'),('T','E'),('T','L'),('T','DN'),('T','U'),('DN','C'),('SD','C'),
     ('H','U'),('L','C'),('Rdi','H'),('Rdf','U')]
NEG=[('Rdf','T'),('Rdi','T')]
DISJ=[('E',['C','U']),('C',['T','Rdf','Rdi']),('U',[]),('DN',['C'])]
def close(S):
    S=set(S); g=True
    while g:
        g=False
        for a,b in POS:
            if a in S and b not in S: S.add(b); g=True
    return frozenset(S)
def vec(S): return tuple(1 if l in S else 0 for l in BOX)
def RR(X,d):
    vals=[sorted({c[i] for c in X}) for i in range(d)]
    def env(i,j):
        m={}
        for c in X: m[c[j]]=max(m.get(c[j],-99),c[i])
        b,o=-99,{}
        for t in sorted(m): b=max(b,m[t]); o[t]=b
        return o
    phi={(i,j):env(i,j) for i in range(d) for j in range(d) if i!=j}
    return {x for x in product(*vals) if all(x[i]<=phi[(i,j)][x[j]] for i in range(d) for j in range(d) if i!=j)}

closed={close(c) for r in range(len(BOX)+1) for c in combinations(BOX,r)}
def negok(S): return not any(a in S and b in S for a,b in NEG)
def disjok(S):
    for ant,ds in DISJ:
        if ant in S and ds and not any(d in S for d in ds): return False
    return True

fams={'POS only':closed,
      'POS+NEG':{c for c in closed if negok(c)},
      'POS+NEG+DISJ':{c for c in closed if negok(c) and disjok(c)}}
print('=== E FOR EACH FAMILY ===')
for k,f in fams.items():
    X={vec(c) for c in f}; R=RR(X,len(BOX))
    print(f'  {k:16s} |X|={len(X):4d}  |R|={len(R):4d}  E={len(R)-len(X)}')

print()
print('=== REFUSAL ACCOUNTING (non-empty closed profiles) ===')
ne=[c for c in closed if c]
r_neg=[c for c in ne if not negok(c)]
r_dis=[c for c in ne if negok(c) and not disjok(c)]
adm  =[c for c in ne if negok(c) and disjok(c)]
print(f'  total non-empty closed        {len(ne)}')
print(f'  REFUSED: exclusion (neg edge) {len(r_neg)}')
print(f'  REFUSED: incomplete (disj)    {len(r_dis)}')
print(f'  ADMITTED                      {len(adm)}')
print()
print('  which disjunction does the incompleteness come from?')
from collections import Counter
cnt=Counter()
for c in r_dis:
    for ant,ds in DISJ:
        if ant in c and ds and not any(d in c for d in ds): cnt[ant]+=1
for k,v in cnt.most_common(): print(f'    unsatisfied {k:4s} -> {v}')
"

