    return frozenset(S)
def negok(S): return not any(a in S and b in S for a,b in NEG)
def disjok(S):
    for a,ds in DISJ:
        if a in S and not any(d in S for d in ds): return False
    return True
def adm(S): return negok(S) and disjok(S)
allclosed={close(c) for r in range(len(BOX)+1) for c in combinations(BOX,r)}
