    for combo in itertools.combinations_with_replacement(range(len(orbs)),k):
        c=Counter(combo)
        if any(v>p for v in c.values()): continue
        ML=sum(orbs[i][0]*n for i,n in c.items()); MS2=sum(orbs[i][1]*n for i,n in c.items())
        cnt[(2*ML,MS2)]+=1
    out=[]
    while cnt:
        ML2max=max(m for (m,s) in cnt)
        MS2max=max(s for (m,s) in cnt if m==ML2max)
        L2,S2=ML2max,MS2max
        for m in range(-L2,L2+1,2):
            for s in range(-S2,S2+1,2):
                if (m,s) in cnt:
                    cnt[(m,s)]-=1
                    if cnt[(m,s)]==0: del cnt[(m,s)]
        out.append((S2,L2))
