            if x[2]>=2: rz(0,1)
            if x[3]>=2: rz(2,2)
            if x[3]>=1: rz(4,1)
            if x[4]>=4: rz(0,1)
            if x[5]>=1: rz(8,1)
            if x[6]>=1: rz(2,2)
            if x[7]>=2: rz(2,2); rz(5,1); rz(8,2)
            if x[8]>=2: rz(7,2)
        return tuple(x)
