CAPS = (3, 3, 1, 3, 1); n_, e_, l_, k_, f_ = CAPS

# ---------- generic operators ----------
def RRset(X, d):
    X = set(X); vals = [sorted({c[i] for c in X}) for i in range(d)]
    def env(i, j):
        m = {}
        for c in X:
            if c[i] > m.get(c[j], -99): m[c[j]] = c[i]
        b, o = -99, {}
        for t in sorted(m): b = max(b, m[t]); o[t] = b
        return o
    phi = {(i, j): env(i, j) for i in range(d) for j in range(d) if i != j}
    return {x for x in product(*vals)
            if all(x[i] <= phi[(i, j)][x[j]] for i in range(d) for j in range(d) if i != j)}
def E(X, d): return len(RRset(X, d)) - len(set(X))
def BPC(X, d):
    X = set(X); vals = [sorted({c[i] for c in X}) for i in range(d)]
    pj = {(i, j): {(c[i], c[j]) for c in X} for i, j in combinations(range(d), 2)}
    return {x for x in product(*vals) if all((x[i], x[j]) in pj[(i, j)] for i, j in combinations(range(d), 2))}

