S9 = set(L9)
def src(c): return (c[0],c[1],c[2],c[7])
def tgt(c): return (c[4],c[5],c[6],c[8])
def legal(t):
    n,l,k,S2 = t; return 1<=n and 0<=l<=n-1 and 1<=k<=4*l+2 and 0<=S2<=k
comp = [c for c in L9 if legal(tgt(c))]
outd, ind = Counter(), Counter()
for c in comp: outd[src(c)] += 1; ind[tgt(c)] += 1
states = sorted(set(outd) | set(ind))
D['quiver'] = {'states': len(states), 'arcs': len(comp),
               'line_edges': sum(ind[s]*outd[s] for s in states),
               'loops': sum(1 for c in comp if src(c)==tgt(c)),
               'in_out': [[ind[s], outd[s]] for s in states]}
adj_up = sum(1 for c in S9 for i in range(9)
             if tuple(list(c[:i])+[c[i]+1]+list(c[i+1:])) in S9)
degs = []
for c in S9:
    dg = 0
    for i in range(9):
        for dd in (1,-1):
            e = list(c); e[i] += dd
            if tuple(e) in S9: dg += 1
    degs.append(dg)
D['hasse'] = {'edges': adj_up, 'deg_min': min(degs), 'deg_max': max(degs),
              'deg_mean': round(sum(degs)/len(degs),2), 'girth': 4,
              'deg_hist': dict(sorted(Counter(degs).items()))}

# ---------- molecular feasibility (recompute, large samples) ----------
def sq(c):
    out = set()
    for i,j in combinations(range(9),2):
        for si in (1,-1):
            for sj in (1,-1):
                a=list(c); a[i]+=si
                b=list(c); b[j]+=sj
                ab=list(c); ab[i]+=si; ab[j]+=sj
                if tuple(a) in S9 and tuple(b) in S9 and tuple(ab) in S9: out.add((i,si,j,sj))
    return frozenset(out)
sqs = {c: sq(c) for c in L9}
pool = sorted(S9); rng = random.Random(1)
mol = []
for m, N in [(2,200000),(3,200000),(4,200000),(6,400000),(8,600000),(10,1000000),(12,1000000)]:
    ok = 0
    for _ in range(N):
        inter = None
        for _ in range(m):
            s = sqs[rng.choice(pool)]
            inter = s if inter is None else inter & s
            if not inter: break
        if inter: ok += 1
    p = ok/N; z = 1.96; dn = 1+z*z/N
    cc = (p+z*z/(2*N))/dn; h = z*math.sqrt(p*(1-p)/N + z*z/(4*N*N))/dn
    mol.append({'m':m,'N':N,'hits':ok,'rate':p*100,'lo':max(0,cc-h)*100,'hi':(cc+h)*100})
D['molecular'] = mol
D['sq_sizes'] = {'min': min(len(v) for v in sqs.values()), 'max': max(len(v) for v in sqs.values()),
                 'mean': round(sum(len(v) for v in sqs.values())/len(sqs),2)}

# ---------- Helly ----------
helly = []
rng2 = random.Random(0)
for m in (3,4,5,6):
    N=200000; pw=0; jt=0; wit=None
    for _ in range(N):
        cells=[rng2.choice(pool) for _ in range(m)]
        sets=[sqs[c] for c in cells]
        if not all(sets[a]&sets[b] for a,b in combinations(range(m),2)): continue
        pw+=1
        inter=sets[0]
        for s in sets[1:]: inter=inter&s
        if inter: jt+=1
        elif wit is None: wit=[list(c) for c in cells]
    helly.append({'m':m,'pairwise':pw,'joint':jt,'pct':jt/pw*100,
                  'witness': wit if m==3 else None,
                  'wsizes': [len(sqs[tuple(c)]) for c in wit] if (m==3 and wit) else None})
D['helly'] = helly

# ---------- violation index ----------
RNG=[range(4),range(3),range(3),range(3),range(5),range(2),range(2),range(3),range(3)]
VN=['X','Sc','IC','U','E','L','SD','DNc','DNd']
def vclose(x):
    x=list(x); g=True
    while g:
        g=False
        def rz(i,v):
            nonlocal g
            if x[i]<v: x[i]=v; g=True
        if x[0]>=3: rz(4,2)
        if x[1]>=2: rz(2,1)
        if x[2]>=2: rz(0,1)
        if x[3]>=2: rz(2,2)
        if x[3]>=1: rz(4,1)
        if x[4]>=4: rz(0,1)
        if x[5]>=1: rz(8,1)
        if x[6]>=1: rz(2,2)
        if x[7]>=2: rz(2,2); rz(5,1); rz(8,2)
        if x[8]>=2: rz(7,2)
    return tuple(x)
allc={vclose(x) for x in product(*RNG)}
V={c for c in allc if not(c[4]>=2 and not(c[2]>=2 or c[3]>=1 or c[0]>=1))}
RV=RRset(V,9); BV=BPC(V,9)
D['vindex']={'cells':len(V),'BPC':len(BV),'R':len(RV),
             'gc_defect':len(BV)-len(V),'env_coarse':len(RV)-len(BV),
             'origin':[0,1,0,0,1,0,0,0,0],'names':VN}
ex=sorted(RV-V)
D['excess']={'n':len(ex),
             'by':{VN[i]: dict(sorted(Counter(c[i] for c in ex).items())) for i in range(9)},
             'factors':[2,5,3,2]}
# projection covariance
proj=[]
for lab,idx in [('X,Sc,U,E',[0,1,3,4]),('+IC',[0,1,2,3,4]),('+L,SD',[0,1,2,3,4,5,6]),('all 9',list(range(9)))]:
    P={tuple(c[i] for i in idx) for c in V}
    proj.append({'label':lab,'coords':len(idx),'cells':len(P),'E':E(P,len(idx))})
D['projection']=proj
# Lambda8 BPC
D['lambda8']={'cells':len(B),'BPC':len(BPC(B,8)),'R':len(RRset(B,8))}
# routes
def route(model):
    def cl(x):
        x=list(x); g=True
        while g:
            g=False
            def rz(i,v):
                nonlocal g
                if x[i]<v: x[i]=v; g=True
            if x[0]>=3:
                rz(4,2)
                if model in ('D','P'): rz(1,2); rz(8,1)
                if model=='D': rz(7,2)
            if x[0]>=1: rz(3,1)
            if x[1]>=2: rz(2,1)
            if x[2]>=2: rz(0,1)
            if x[3]>=2: rz(2,2)
            if x[3]>=1: rz(4,1)
            if x[4]>=4: rz(0,1)
            if x[5]>=1: rz(8,1)
            if x[6]>=1: rz(2,2)
            if x[7]>=2: rz(2,2); rz(5,1); rz(8,2)
            if x[8]>=2: rz(7,2)
        return tuple(x)
    a={cl(x) for x in product(*RNG)}
    ok={c for c in a if not(c[4]>=2 and not(c[2]>=2 or c[3]>=1 or c[0]>=1))}
    o=cl((0,1,0,0,1,0,0,0,0))
    cov={(p,q) for p in ok for q in ok if p!=q and all(q[i]>=p[i] for i in range(9))
         and not any(r!=p and r!=q and all(r[i]>=p[i] for i in range(9)) and all(q[i]>=r[i] for i in range(9)) for r in ok)}
    ad=defaultdict(list)
    for p,q in cov: ad[p].append(q)
    from collections import deque
    prev={o:None}; dq=deque([o])
    while dq:
        c=dq.popleft()
        for n in ad[c]:
            if n not in prev: prev[n]=c; dq.append(n)
    T=[c for c in ok if c[0]==3 and c in prev]
    t=min(T,key=lambda c:sum(c)); path=[]; c=t
    while c is not None: path.append(list(c)); c=prev.get(c)
    return {'cells':len(ok),'dest':list(t),'steps':len(path)-1,'path':list(reversed(path))}
D['routes']={'model-independent':route('M'),'P-CTC':route('P'),'D-CTC':route('D')}

# ---------- multilattice ----------
def cap(l,m): return m*(4*l+2)
def base_m(caps,m):
    nn,ee,ll,kk,ff=caps; cells=[]
    for n in range(1,nn+1):
      for l in range(0,min(n-1,ll)+1):
        for k in range(1,min(cap(l,m),kk)+1):
          for q in range(0,k+1):
            for S2 in range(0,k+1):
              for e in range(1,ee+1):
                for f in range(0,min(e-1,ff)+1):
                  for g in range(0,min(cap(f,m),q)+1):
                    cells.append((n,l,k,q,e,f,g,S2))
    return cells
W=(4,4,2,12,2)
A1,A2=set(base_m(W,1)),set(base_m(W,2))
D['containment']={'caps':list(W),'m1':len(A1),'m2':len(A2),
                  'outward_lost':len(A1-A2),'inward_lost':len(A2-A1),
                  'proj_m1':[[min(c[i] for c in A1),max(c[i] for c in A1)] for i in range(8)],
                  'proj_m2':[[min(c[i] for c in A2),max(c[i] for c in A2)] for i in range(8)],
                  'names':['n','l','k','q','e','f','g','2S']}
# l-bound family
def base_phi(caps,phi):
    nn,ee,ll,kk,ff=caps; cells=[]
    for n in range(1,nn+1):
      for l in range(0,min(phi(n),ll)+1):
        if l<0: continue
        for k in range(1,min(4*l+2,kk)+1):
          for q in range(0,k+1):
            for S2 in range(0,k+1):
              for e in range(1,ee+1):
                for f in range(0,min(e-1,ff)+1):
                  for g in range(0,min(4*f+2,q)+1):
                    cells.append((n,l,k,q,e,f,g,S2))
    return cells
LC=(4,4,3,10,3)
fam=[('l<=n-1',lambda n:n-1,True),('l<=n',lambda n:n,True),('l<=2(n-1)',lambda n:2*(n-1),True),
     ('l<=n//2',lambda n:n//2,True),('l<=|n-3|',lambda n:abs(n-3),False),('l<=3-|n-3|',lambda n:3-abs(n-3),False)]
D['lbound']=[]
for lab,phi,mono in fam:
    X=base_phi(LC,phi)
    D['lbound'].append({'label':lab,'monotone':mono,'cells':len(set(X)),'E':E(X,8),
                        'phi':[max(0,min(phi(n),3)) for n in range(1,5)]})

# ---------- NEW: order and measure (exact, not sampled) ----------
Bl=sorted(B); N=len(Bl); comp_pairs=0; samen=0
for a in range(N):
    ca=Bl[a]
    for b in range(a+1,N):
        cb=Bl[b]
        le=True; ge=True
        for i in range(8):
            if ca[i]>cb[i]: le=False
            if ca[i]<cb[i]: ge=False
            if not le and not ge: break
        if le or ge:
            comp_pairs+=1
            if ca[0]==cb[0]: samen+=1
tot=N*(N-1)//2
D['order']={'cells':N,'pairs':tot,'comparable':comp_pairs,
            'incomparable':tot-comp_pairs,
            'comparable_pct':comp_pairs/tot*100,
            'samen_of_comparable':samen,
            'samen_pct':samen/comp_pairs*100}

# ---------- NEW: synthetic blindness panels ----------
def mkpanel(pred):
    return sorted({(x,y) for x in range(8) for y in range(8) if pred(x,y)})
pan={}
pan['monotone']   = mkpanel(lambda x,y: y <= x)                     # y <= phi(x), monotone
pan['decreasing'] = mkpanel(lambda x,y: y <= 7-x)                   # decreasing bound
pan['parity']     = mkpanel(lambda x,y: y<=x and (x-y)%2==0)        # congruence
pan['ternary']    = mkpanel(lambda x,y: y<=x)                       # placeholder; 3D handled below
for k,v in pan.items():
    Xs=set(v); vals=[sorted({c[i] for c in Xs}) for i in range(2)]
    R=RRset(Xs,2)
    pan[k]={'cells':[list(c) for c in sorted(Xs)],'R':[list(c) for c in sorted(R)],'E':len(R)-len(Xs)}
# genuine ternary: z <= x+y in a 3-cube, projected to (x,y)
T3={(x,y,z) for x in range(5) for y in range(5) for z in range(5) if z<=max(x,y) and z<=x+y-1}
R3=RRset(T3,3)
pan['ternary']={'cells':len(T3),'R':len(R3),'E':len(R3)-len(T3),
                'proj_cells':[list(c) for c in sorted({(c[0],c[1]) for c in T3})],
                'proj_R':[list(c) for c in sorted({(c[0],c[1]) for c in R3})]}
D['panels']=pan

json.dump(D, open('/home/claude/paper/data.json','w'), indent=1)
print('datasets written:', ', '.join(sorted(D)))
print('order:', D['order'])
print('vindex:', D['vindex'])

