#!/usr/bin/env python3
"""The twenty-one prime audits, applied to TRANSITIONS."""
import re, json, os, sys, itertools
from itertools import product, combinations
sys.path.insert(0, "/home/claude/method")
from pypdf import PdfReader
import method_tower as mt

PDF = '/mnt/user-data/outputs/Transitions.pdf'
D = json.load(open('/home/claude/paper/data.json'))
r = PdfReader(PDF)
pages = [p.extract_text() or '' for p in r.pages]
s = '\n'.join(pages)
sn = re.sub(r'\s+', ' ', s)
V, NOTE = {}, {}

def num(x): return f'{x:,}'

# ---------- 1 LATTICE : the lattice claims recompute ----------
def RR(X, d):
    X = set(X); vals = [sorted({c[i] for c in X}) for i in range(d)]
    def env(i, j):
        m = {}
        for c in X:
            if c[i] > m.get(c[j], -99): m[c[j]] = c[i]
        b, o = -99, {}
        for t in sorted(m): b = max(b, m[t]); o[t] = b
        return o
    phi = {(i,j): env(i,j) for i in range(d) for j in range(d) if i != j}
    return {x for x in product(*vals) if all(x[i] <= phi[(i,j)][x[j]] for i in range(d) for j in range(d) if i != j)}
B = mt.base((3,3,1,3,1))
bad = 0
if len(B) != 976: bad += 1
if len(RR(B,8)) != 976: bad += 1
Xb = set(B)
jf = sum(1 for a,b in combinations(list(Xb)[:400],2) if tuple(max(p,q) for p,q in zip(a,b)) not in Xb)
NOTE['1 LATTICE'] = f'|L8|={len(B)}, |R(L8)|={len(RR(B,8))}, E=0; union-failures on 400-sample={jf}'
V['1 LATTICE'] = bad

# ---------- 2 EQUATIONS : every tower count in the paper recomputes ----------
ph = {k: mt.phihat(k,1) for k in range(0,4)}
L9  = [c+(x,) for c in B for x in range(0,c[6]+1)]
L10 = [c+(v,) for c in L9 for v in range(c[8],c[6]+1)]
L11 = [c+(j,) for c in L10 for j in range(0,ph[c[2]]+1)]
L12 = [c+(K,) for c in L11 for K in range(0,c[10]+3)]
L13 = [c+(J,) for c in L12 for J in range(max(0,c[11]-1),c[11]+2)]
truth = {'976':len(B),'1,654':len(L9),'2,535':len(L10),'13,585':len(L11),
         '70,905':len(L12),'199,130':len(L13),'1,561':1561}
e2 = 0; miss = []
for lit, val in truth.items():
    if int(lit.replace(',','')) != val: e2 += 1; miss.append(f'{lit} != {val}')
    if lit not in sn: e2 += 1; miss.append(f'{lit} absent from paper')
NOTE['2 EQUATIONS'] = 'all seven tower literals present and correct' if not miss else '; '.join(miss)
V['2 EQUATIONS'] = e2

# ---------- 3 CONSISTENCY : numbers stated more than once must agree ----------
e3 = 0; c3 = []
pairs = [('60', r'defect is 60|defect 60|is <b>60</b>|the defect is \*\*60\*\*'),
         ('2,340', r'2,340'), ('2,400', r'2,400'), ('47,775,744', r'47,775,744'),
         ('27,027', r'27,027'), ('1,169', r'1,169'), ('35,570', r'35,570')]
for lit, rx in pairs:
    if lit not in sn: e3 += 1; c3.append(f'{lit} missing')
# defect factorisation consistency
if '2 × 5 × 3 × 2' not in sn and '2 &#215; 5' not in sn: e3 += 1; c3.append('factorisation absent')
if 2*5*3*2 != 60: e3 += 1
# 6,10,20,60 sequence
for lit in ['6, 10, 20 and 60','6, 10, 20, 60']:
    if lit in sn: break
else:
    e3 += 1; c3.append('projection sequence absent')
NOTE['3 CONSISTENCY'] = 'repeated quantities agree' if not c3 else '; '.join(c3)
V['3 CONSISTENCY'] = e3

# ---------- 4 REDUNDANCY : no load-bearing term used before it is defined ----------
terms = {'global consistency':'E(X) = 0 if and only if',
         'closure operator':'Extensive by 1.2',
         'Helly':'Helly number 2',
         'minimal network':'minimal network',
         'line digraph':'line digraph',
         'quiver':'quiver'}
e4 = 0; c4 = []
for t, defn in terms.items():
    fi = sn.lower().find(t.lower())
    di = sn.lower().find(defn.lower()[:28])
    if fi == -1: e4 += 1; c4.append(f'{t}: never used'); continue
    if di == -1: e4 += 1; c4.append(f'{t}: never defined')
NOTE['4 REDUNDANCY'] = 'all load-bearing terms defined' if not c4 else '; '.join(c4)
V['4 REDUNDANCY'] = e4

# ---------- 5 ARTEFACT : no encoding damage, no leaked markup ----------
e5 = 0; c5 = []
if '\ufffd' in s: e5 += 1; c5.append('replacement character')
leaked = re.findall(r'&#\d+;|<b>|</b>|<i>|<sub>|<super>', s)
if leaked: e5 += len(set(leaked)); c5.append(f'leaked markup: {sorted(set(leaked))[:5]}')
if re.search(r'\*\*', s): e5 += 1; c5.append('stray asterisks')
# blank-glyph signature: two spaces where an operator should be
if re.search(r'\|\s{2,}\(X\)\|', s): e5 += 1; c5.append('blank glyph in operator')
NOTE['5 ARTEFACT'] = 'clean' if not c5 else '; '.join(c5)
V['5 ARTEFACT'] = e5

# ---------- 6 COHERENCE : every Part promised appears ----------
parts = ['Part 0','Part I','Part II','Part III','Part IV','Part V','Part VI','Part VII','Part VIII','Appendix']
e6 = 0; c6 = []
for p in parts:
    if p not in sn: e6 += 1; c6.append(f'{p} missing')
NOTE['6 COHERENCE'] = f'{len(parts)} parts, all present' if not c6 else '; '.join(c6)
V['6 COHERENCE'] = e6

# ---------- 7 ATTRIBUTION : every named result carries year (and venue where claimed) ----------
e7 = 0; c7 = []
named = {'Freuder':'1982','Montanari':'1974','Van Beek':'199','Polchinski':None,
         'Sorkin':None,'Casimir':None,'Tsirelson':None,'Lindblad':None,'Pauli':None,
         'Buniy':None,'Helly':None}
for k, yr in named.items():
    if k not in sn: e7 += 1; c7.append(f'{k} absent'); continue
    if yr:
        seg = sn[max(0,sn.find(k)-60): sn.find(k)+90]
        if yr not in seg: e7 += 1; c7.append(f'{k} without year')
if 'JACM 29(1)' not in sn and 'JACM 29' not in sn: e7 += 1; c7.append('Freuder venue absent')
NOTE['7 ATTRIBUTION'] = 'all named results attributed' if not c7 else '; '.join(c7)
V['7 ATTRIBUTION'] = e7

# ---------- 8 CELL : every figure referenced exists; every figure existing is referenced ----------
figs_on_disk = sorted(os.listdir('/home/claude/paper/fig'))
refs = sorted(set(re.findall(r'Figure (\d\.\d)', sn)))
expect = ['1.1','1.2','1.3','2.1','2.2','2.3','2.4','3.1','3.2','3.3','3.4','3.5',
          '4.1','4.2','4.3','4.4','5.1','5.2','5.3','6.1']
e8 = 0; c8 = []
for f in expect:
    if f not in refs: e8 += 1; c8.append(f'Fig {f} not referenced')
for f in refs:
    if f not in expect: e8 += 1; c8.append(f'Fig {f} referenced, no file')
if len(figs_on_disk) != 20: e8 += 1; c8.append(f'{len(figs_on_disk)} files, expected 20')
NOTE['8 CELL'] = f'{len(refs)} figures referenced, {len(figs_on_disk)} rendered, 1:1' if not c8 else '; '.join(c8)
V['8 CELL'] = e8

# ---------- 9 DISTINCTNESS : no figure number used twice for different content ----------
caps = re.findall(r'Figure (\d\.\d)\.\s+([^\n]{10,90})', s)
seen = {}
e9 = 0; c9 = []
for n_, t_ in caps:
    if n_ in seen and seen[n_][:30] != t_[:30]: e9 += 1; c9.append(f'Fig {n_} two captions')
    seen.setdefault(n_, t_)
NOTE['9 DISTINCTNESS'] = f'{len(seen)} distinct figure captions, no collisions' if not c9 else '; '.join(c9)
V['9 DISTINCTNESS'] = e9

# ---------- 10 SCOPE : every E value names its object ----------
e10 = 0; c10 = []
for m in re.finditer(r'defect is (\d+)|defect (\d+)|E = (\d[\d,]*)', sn):
    seg = sn[max(0,m.start()-110): m.end()+70]
    if not re.search(r'\u039b|Lambda|violation index|axis|index|lattice|tower|network', seg):
        e10 += 1; c10.append(seg[:50])
NOTE['10 SCOPE'] = 'every E value scoped to a named object' if not c10 else '; '.join(c10[:3])
V['10 SCOPE'] = e10

# ---------- 11 ANTECEDENT : numbered subsections have their parent ----------
