    out=[]; cur=[None]*d
    def rec(i):
        if i==d:
            t=tuple(cur)
            if t not in S: out.append(t)
            return
        for v in vals[i]:
            ok=True
            for j in range(i):
                if v>phi[(i,j)][cur[j]] or cur[j]>phi[(j,i)][v]: ok=False; break
            if ok: cur[i]=v; rec(i+1)
