def d_f(c): return c[Xe]+c[Ug]+abs(c[Np]-3)+c[EO]+dP(c)
def s_f(c): return (1 if c[Xe]>0 else 0)+(1 if c[Ug]>0 else 0)+(1 if c[Np]!=3 else 0)+(1 if c[EO]>0 else 0)+sP(c)
