def close9(x):
    x=list(x); g=True
    while g:
        g=False
        def rz(i,v):
            nonlocal g
            if x[i]<v: x[i]=v; g=True
        if x[0]>=3: rz(4,2)
        if x[1]>=2: rz(2,1)
        if x[2]>=2: rz(0,1)
        if x[3]>=2: rz(2,2)
        if x[3]>=1: rz(4,1)
        if x[4]>=4: rz(0,1)
        if x[5]>=1: rz(8,1)
        if x[6]>=1: rz(2,2)
        if x[7]>=2: rz(2,2); rz(5,1); rz(8,2)
        if x[8]>=2: rz(7,2)
    return tuple(x)

def envelopes(S,d):
    S=set(S); vals=[sorted({c[i] for c in S}) for i in range(d)]
    phi={}
    for i in range(d):
        for j in range(d):
            if i==j: continue
            m={}
            for c in S:
                if c[i]>m.get(c[j],-99): m[c[j]]=c[i]
            b,o=-99,{}
            for t in sorted(m): b=max(b,m[t]); o[t]=b
            phi[(i,j)]=o
    return vals,phi

def closure(S,d,want_excess=False):
    """Backtracking count of R(S); returns (E, excess list or None, box)."""
    S=set(S); vals,phi=envelopes(S,d)
    box=1
    for v in vals: box*=len(v)
    tot=0; ex=[]; cur=[None]*d
    def rec(i):
        nonlocal tot
        if i==d:
            tot+=1
            if want_excess:
                t=tuple(cur)
                if t not in S: ex.append(t)
            return
        for v in vals[i]:
            ok=True
            for j in range(i):
                if v>phi[(i,j)][cur[j]] or cur[j]>phi[(j,i)][v]: ok=False; break
            if ok: cur[i]=v; rec(i+1)
        cur[i]=None
    rec(0)
    return tot-len(S), (ex if want_excess else None), box

