def nonmono(S,d):
    bad=0
    for i in range(d):
        for j in range(d):
            if i==j: continue
            m={}
            for c in S: m[c[j]]=max(m.get(c[j],-99),c[i])
            s=[m[v] for v in sorted(m)]
            if s!=sorted(s) and s!=sorted(s,reverse=True): bad+=1
    return bad
